          self.capacity = capacity
          self.cache = {}

      def remove(self):
          for k in self.cache:
              return k

      def get(self, key):
          if key in self.cache:
              value = self.cache.pop(key)  # move to end
              self.cache[key] = value  # updated value
              return value
          return -1

      def put(self, key, value):
          if key in self.cache:
              self.cache.pop(key)  # official docs say removing
          elif len(self.cache) >= self.capacity:
              first_key_in_cache = self.remove()
              del self.cache[first_key_in_cache]  # remove the first
          self.cache[key] = value

